import {esc} from './ui.mjs';
import {nearestSubstitutes} from './chord-relationships-v2.mjs';
export function renderPartialMatches(s,analysis){
 if(!analysis||analysis.projection.basisStatus!=='mapped')return '';
 const partials=analysis.occurrences.bestPartialOccurrences;
 if(!partials.length)return '';
 return `<details class="chord-v2-partials"><summary>Partial matches · missing mapped members</summary><p class="catalogue-help">Ranked by unique matched pitch classes, then generator span and root degree. All roots of this chord share the same root-relative tuning errors. Showing the best ${Math.min(6,partials.length)} of up to 24 retained partial embeddings.</p>${partials.slice(0,6).map(o=>{const substitutes=nearestSubstitutes(s,analysis.projection,o,{tolerance:analysis.projection.tolerance});return `<div class="chord-v2-partial"><b>Root ${o.root} · ${o.matchedCardinality}/${o.requiredCardinality} exact pitch classes</b><p>Missing: ${o.missingCoordinates.map(m=>`${m.ratio} at (${m.coordinate.join(', ')})`).join(' · ')}</p>${substitutes.length?`<details><summary>Approximate substitutes — not exact members</summary><p>Signed deviations from the missing mapped pitch; already occupied degrees are excluded. Options for each missing member are independent.</p>${substitutes.map(v=>`<p>${v.ratio} → degree ${v.degree} · ${v.errorCents>=0?'+':''}${v.errorCents.toFixed(3)}¢</p>`).join('')}</details>`:'<p class="catalogue-help">No unused-degree substitute within tolerance.</p>'}</div>`;}).join('')}</details>`;
}
export function renderRelationships(r){return `<details class="chord-v2-relationships"><summary>JI relationships & tempered aliases</summary><button data-catalogue-action="v2-relationships">Find relationships</button>${r?`<p role="status">${r.status==='loading'?'Searching':r.status==='cancelled'?'Cancelled':'Searched'} ${r.done}/${r.total} bounded candidates${r.limited?' · display capped at 24 per group':''}</p>${r.status==='loading'?'<button data-catalogue-action="v2-cancel-relationships">Cancel relationships</button>':''}${[['subsets','Exact JI subsets'],['supersets','Exact JI supersets'],['aliases','Tempered aliases (same period-class shape)']].map(([key,label])=>`<h4>${label}</h4>${r[key].length?r[key].map(c=>`<button data-catalogue-action="v2-chord" data-id="${esc(c.text)}">${esc(c.label)}</button>`).join(''):'<p class="catalogue-help">None found in the searched candidates.</p>'}`).join('')}`:''}</details>`;}
